from pathlib import Path
import subprocess,hashlib,json,os
sha=lambda p:hashlib.file_digest(Path(p).open('rb'),'sha256').hexdigest()
assert os.statvfs('.').f_bavail*os.statvfs('.').f_frsize>12*2**30
previous=Path('target/thos-live.img');assert sha(previous)=='9c4ed07d1350586d7e013c011c96c718ec6259c7b976a6b9135e44866c82adcf'
parent=json.loads(Path('target/thos-live-2026-10-24-nls-build-manifest.json').read_text());qa=json.loads(Path('target/thos-format-qa-2026-10-24-manifest.json').read_text());assert qa['status'].startswith('QA verified')
kernel=Path(qa['kernel']);dll=Path(qa['kernel32x']);assert sha(kernel)==qa['kernel_sha256'] and sha(dll)==qa['kernel32x_sha256']
for f,h in qa['sources'].items():assert sha(f)==h,f
base_root=Path(parent['root']);assert sha(base_root)==parent['root_sha256']
root=Path('target/live-root-format-2026-10-24.ext2');image=Path('target/thos-live-format-2026-10-24.img');assert not root.exists() and not image.exists()
subprocess.run(['cp','--sparse=always','--reflink=auto',str(base_root),str(root)],check=True)
for cmd in ['rm /Windows/System32/kernel32x.dll',f'write {dll} /Windows/System32/kernel32x.dll']:subprocess.run(['/usr/sbin/debugfs','-w','-R',cmd,str(root)],check=True,capture_output=True)
readback=Path('/tmp/thos-live-format-readback-2026-10-24.dll');readback.unlink(missing_ok=True);subprocess.run(['/usr/sbin/debugfs','-R',f'dump /Windows/System32/kernel32x.dll {readback}',str(root)],check=True,capture_output=True);assert sha(readback)==sha(dll)
subprocess.run(['/usr/sbin/e2fsck','-fn',str(root)],check=True);assert root.stat().st_size==base_root.stat().st_size
subprocess.run(['cp','--sparse=always','--reflink=auto',str(previous),str(image)],check=True)
for source,destination in [(kernel,'::boot/thos-kernel'),(root,'::boot/thos-root.ext2')]:
 subprocess.run(['mcopy','-o','-i',str(image)+'@@1048576',str(source),destination],check=True)
 p=subprocess.Popen(['mtype','-i',str(image)+'@@1048576',destination],stdout=subprocess.PIPE);h=hashlib.file_digest(p.stdout,'sha256').hexdigest();assert p.wait()==0 and h==sha(source)
h=sha(image);size=image.stat().st_size;subprocess.run(['fallocate','--dig-holes',str(image)],check=True);assert sha(image)==h and image.stat().st_size==size
